python3 -c "
import json

with open('/data/inventory.json', 'r') as f:
    data = json.load(f)

# Let's inspect the data type/structure first
if isinstance(data, list):
    for item in data:
        if item.get('quantity', 0) < 10:
            print(item.get('name'))
elif isinstance(data, dict):
    # Could be {'items': [...]} or similar
    items = data.get('items', data.get('inventory', []))
    if not items and all(isinstance(v, dict) for v in data.values()):
        # maybe dict of items
        items = list(data.values())
    for item in items:
        if item.get('quantity', 0) < 10:
            print(item.get('name'))
"

